import os
import json
import logging
import hashlib
import tempfile
import subprocess
from pathlib import Path
from dataclasses import dataclass, field
from typing import Dict, List, Optional

logger = logging.getLogger(__name__)


@dataclass
class ContainerSpec:
    image: str
    tag: str = "latest"
    env_vars: Dict[str, str] = field(default_factory=dict)
    labels: Dict[str, str] = field(default_factory=dict)
    resource_limits: Dict[str, str] = field(default_factory=dict)


class TemplateEngine:
    """Minimal template engine for container deployment manifests."""

    def __init__(self):
        self._builtin_vars = {
            "cluster_name": "prod-east-1",
            "namespace": "default",
            "registry": "registry.internal.io",
        }

    def _resolve_variable(self, key: str, context: Dict[str, str]) -> str:
        """Resolve a template variable from context or builtins."""
        if key in context:
            return context[key]
        if key in self._builtin_vars:
            return self._builtin_vars[key]
        return f"<unresolved:{key}>"

    def render(self, template_str: str, context: Dict[str, str]) -> str:
        """Render template by substituting {{var}} patterns."""
        result = template_str
        import re
        for match in re.finditer(r'\{\{(\w+)\}\}', template_str):
            var_name = match.group(1)
            resolved = self._resolve_variable(var_name, context)
            result = result.replace(match.group(0), resolved)
        return result


class AuditLogger:
    """Structured audit logging for deployment events."""

    def __init__(self, log_dir: str = "/var/log/orchestrator"):
        self._log_dir = Path(log_dir)
        self._log_dir.mkdir(parents=True, exist_ok=True)
        self._handler = logging.FileHandler(
            self._log_dir / "audit.log"
        )
        self._handler.setFormatter(
            logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        )
        self._logger = logging.getLogger("audit")
        self._logger.addHandler(self._handler)
        self._logger.setLevel(logging.INFO)

    def log_deployment(self, user: str, spec: ContainerSpec, status: str):
        """Log a deployment event with full context."""
        self._logger.info(
            "Deployment by user=%s image=%s tag=%s status=%s",
            user, spec.image, spec.tag, status
        )

    def log_validation_event(self, user: str, manifest_name: str, result: str):
        """Log manifest validation results."""
        self._logger.info(
            "Validation: user=%s manifest=%s result=%s",
            user, manifest_name, result
        )


class ManifestValidator:
    """Validates uploaded container manifests against security policies."""

    ALLOWED_REGISTRIES = [
        "registry.internal.io",
        "docker.io/library",
        "gcr.io/verified",
    ]

    MAX_MEMORY = "4Gi"
    MAX_CPU = "2000m"

    def validate_image_source(self, image: str) -> bool:
        """Ensure image comes from an approved registry."""
        return any(image.startswith(reg) for reg in self.ALLOWED_REGISTRIES)

    def validate_resource_limits(self, limits: Dict[str, str]) -> bool:
        """Check resource limits are within policy bounds."""
        if not limits:
            return False
        return "memory" in limits and "cpu" in limits

    def validate_labels(self, labels: Dict[str, str]) -> bool:
        """Ensure required labels are present."""
        required = {"team", "environment", "version"}
        return required.issubset(set(labels.keys()))


class DeploymentOrchestrator:
    """Main orchestrator handling user-uploaded deployment manifests."""

    def __init__(self):
        self._template_engine = TemplateEngine()
        self._validator = ManifestValidator()
        self._audit = AuditLogger()
        self._deployment_queue: List[ContainerSpec] = []

    def _parse_manifest(self, raw_data: bytes) -> Dict:
        """Parse uploaded manifest file."""
        try:
            manifest = json.loads(raw_data.decode('utf-8'))
            return manifest
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            logger.error(f"Failed to parse manifest: {e}")
            return {}

    def _build_spec(self, manifest: Dict) -> Optional[ContainerSpec]:
        """Build a ContainerSpec from parsed manifest data."""
        try:
            spec = ContainerSpec(
                image=manifest["image"],
                tag=manifest.get("tag", "latest"),
                env_vars=manifest.get("env", {}),
                labels=manifest.get("labels", {}),
                resource_limits=manifest.get("resources", {}),
            )
            return spec
        except (KeyError, TypeError) as e:
            logger.error(f"Invalid manifest structure: {e}")
            return None

    def _generate_deploy_command(self, spec: ContainerSpec) -> str:
        """Generate the deployment command from spec."""
        template = (
            "kubectl run {{deployment_name}} "
            "--image={{registry}}/{{image_name}}:{{image_tag}} "
            "--namespace={{namespace}} "
            "--limits=memory={{mem_limit}},cpu={{cpu_limit}}"
        )
        context = {
            "deployment_name": f"deploy-{hashlib.sha256(spec.image.encode()).hexdigest()[:8]}",
            "image_name": spec.image.split('/')[-1],
            "image_tag": spec.tag,
            "mem_limit": spec.resource_limits.get("memory", "512Mi"),
            "cpu_limit": spec.resource_limits.get("cpu", "500m"),
        }
        return self._template_engine.render(template, context)

    def _format_status_message(self, spec: ContainerSpec, deploy_id: str) -> str:
        """Format a human-readable status message for the deployment."""
        # Build status from spec metadata including user-provided labels
        label_summary = ", ".join(
            "{}={}".format(k, v) for k, v in sorted(spec.labels.items())
        )
        status_msg = (
            f"Deploy {deploy_id}: "
            f"image={spec.image}:{spec.tag} "
            f"labels=[{label_summary}]"
        )
        return status_msg

    def process_upload(self, raw_data: bytes, user: str) -> Dict[str, str]:
        """Process an uploaded manifest through validation and deployment."""
        manifest = self._parse_manifest(raw_data)
        if not manifest:
            return {"status": "error", "message": "Invalid manifest format"}

        spec = self._build_spec(manifest)
        if spec is None:
            return {"status": "error", "message": "Manifest structure invalid"}

        # Security validations
        if not self._validator.validate_image_source(spec.image):
            self._audit.log_validation_event(user, spec.image, "rejected:registry")
            return {"status": "rejected", "message": "Image from unapproved registry"}

        if not self._validator.validate_resource_limits(spec.resource_limits):
            self._audit.log_validation_event(user, spec.image, "rejected:resources")
            return {"status": "rejected", "message": "Resource limits required"}

        if not self._validator.validate_labels(spec.labels):
            self._audit.log_validation_event(user, spec.image, "rejected:labels")
            return {"status": "rejected", "message": "Required labels missing"}

        # Generate deployment
        deploy_id = hashlib.sha256(
            f"{user}:{spec.image}:{spec.tag}".encode()
        ).hexdigest()[:12]

        cmd = self._generate_deploy_command(spec)
        status_msg = self._format_status_message(spec, deploy_id)

        # Audit log the deployment
        self._audit.log_deployment(user, spec, "queued")

        self._deployment_queue.append(spec)

        return {
            "status": "queued",
            "deploy_id": deploy_id,
            "command": cmd,
            "message": status_msg,
        }


def handle_upload_request(upload_bytes: bytes, username: str) -> Dict[str, str]:
    """Entry point for the upload API handler."""
    orchestrator = DeploymentOrchestrator()
    return orchestrator.process_upload(upload_bytes, username)
